import { useEffect, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";

const WHATSAPP_NUMBER = "917418804656";

export default function Membership() {
  const [branches, setBranches] = useState({});
  const [active, setActive] = useState("");

  useEffect(() => {
    fetch("http://localhost:5001/membership")
      .then((res) => res.json())
      .then((data) => {
        setBranches(data);
        setActive(Object.keys(data)[0]);
      });
  }, []);

  const whatsapp = (branch) =>
    `https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(
      `Hello, I want to join ${branch} branch (BodyZeal Fitworks)`
    )}`;

  if (!branches[active]) return null;

  return (
    <section className="bg-black text-white py-32 px-6">
      <div className="max-w-6xl mx-auto">
        <div className="flex justify-center gap-4 mb-12">
          {Object.keys(branches).map((b) => (
            <button
              key={b}
              onClick={() => setActive(b)}
              className={`px-6 py-2 rounded-full ${
                active === b
                  ? "bg-[#e9b21a] text-black"
                  : "border border-white/20"
              }`}
            >
              {b}
            </button>
          ))}
        </div>

        <AnimatePresence mode="wait">
          <motion.div
            key={active}
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: 30 }}
            className="grid md:grid-cols-2 gap-10"
          >
            <div className="border border-white/10 p-8 rounded-xl">
              {branches[active].memberships.map(([l, p], i) => (
                <div key={i} className="flex justify-between mb-3">
                  <span>{l}</span>
                  <span>{p}</span>
                </div>
              ))}
            </div>

            <div className="border border-white/10 p-8 rounded-xl">
              {branches[active].addons.map(([l, p], i) => (
                <div key={i} className="flex justify-between mb-3">
                  <span>{l}</span>
                  <span>{p}</span>
                </div>
              ))}

              <a
                href={whatsapp(active)}
                target="_blank"
                className="mt-8 block text-center bg-[#e9b21a] text-black py-4 rounded-full font-bold"
              >
                Join at {active}
              </a>
            </div>
          </motion.div>
        </AnimatePresence>
      </div>
    </section>
  );
}
